'use client'

import * as React from 'react'

// A side that is a player is rendered by `identity`, and both scores are
// `stat`s. This file writes no avatar and renders no number of its own.
import { Identity, type IdentityPlayer } from './identity'
import { Stat } from './stat'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Versus, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './versus.css'

/**
 * Versus: two sides, head to head.
 *
 * Specimen 3f's bar: each side's player or team, each side's score, and a split
 * showing who holds what share of the two. Two sides and never three: a board
 * of many is a `leaderboard`, and this is the one comparison a player is in.
 *
 * **A side is a player or a team, and they are not the same thing.** A team has
 * no avatar case and no presence, and a player may be on a team's side without
 * the side being them, so a side carries `data-gs-side` always and then
 * `data-gs-player` or `data-gs-team` depending on what it stands for. The
 * player's side does not also carry `data-gs-you`, because `data-gs-side` has
 * already said it.
 *
 * It performs nothing. It does not decide who is winning, does not settle the
 * head-to-head and does not count. The host owns both numbers and the outcome.
 */

/** How the head-to-head finished. The words that go with them are past tense. */
export type VersusOutcome = 'win' | 'loss' | 'draw'

export interface VersusSide {
  /**
   * Who this side is, when it is a person. `null` is the signed-out case and
   * `identity` renders it; leave it out entirely for a side that is a team.
   */
  player?: IdentityPlayer | null
  /** The team this side stands for, when it stands for one. Rides `data-gs-team`. */
  team?: string
  /** What to call the side. Required for a team, optional for a player. */
  label?: string
  /** This side's number. Rendered by `stat`, so it carries `data-gs-value`. */
  score: number
  /** How it finished, once the host knows. */
  outcome?: VersusOutcome
}

export interface VersusProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** The side belonging to the player holding the device. */
  player: VersusSide
  /** The other one. */
  opponent: VersusSide
  /** The surface's accessible name. */
  label?: string
  /** The word between the two sides. */
  divider?: React.ReactNode
  /** The word beside each number. Defaults to `stat`'s own. */
  scoreLabel?: string
  /** Render a score as something other than the bare number. */
  formatScore?: (value: number) => string
  /**
   * Show the bar dividing the two scores by share. Off where the two numbers
   * are not a whole that can be split, a time against a time for instance.
   */
  split?: boolean
}

/**
 * The words that go with the states. Past tense, fixed by the attribute
 * contract's table: the attribute's value is `win` and what a player hears is
 * "won".
 */
const OUTCOME_WORD: Record<VersusOutcome, string> = {
  win: 'won',
  loss: 'lost',
  draw: 'drawn',
}

/**
 * The outcome as a mark, because a side that only changes colour tells a
 * colour-blind player nothing. Inline SVG taking `currentColor`.
 */
function OutcomeGlyph({ outcome }: { outcome: VersusOutcome }) {
  const common = {
    width: 14,
    height: 14,
    viewBox: '0 0 16 16',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 2.4,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
    'aria-hidden': true,
  }
  if (outcome === 'win') return <svg {...common}><path d="M3 10.5L8 5l5 5.5" /></svg>
  if (outcome === 'loss') return <svg {...common}><path d="M3 5.5L8 11l5-5.5" /></svg>
  return <svg {...common}><path d="M3.5 6h9M3.5 10h9" /></svg>
}

/** What a side is called when nothing else says. */
const DEFAULT_LABEL = { player: 'You', opponent: 'Opponent' } as const

/**
 * The player's share of the two scores, as a fraction of the bar.
 *
 * Two zeroes are a half each rather than a division by nought, which is what
 * the bar looks like before either side has scored.
 *
 * A negative score is a real thing in a penalty game, and it breaks the ratio
 * rather than merely overrunning the track: minus fifty against ten is a total
 * of minus forty, and minus fifty over minus forty is 1.25, a full bar for the
 * side that is losing badly. So each score is floored at nought before the
 * division, and a side in deficit holds none of the bar. `data-gs-value` on
 * each stat still carries the real number.
 */
function share(player: number, opponent: number): number {
  const mine = Math.max(0, player)
  const theirs = Math.max(0, opponent)
  const total = mine + theirs
  if (total === 0) return 0.5
  return mine / total
}

function Side({
  side,
  which,
  scoreLabel,
  formatScore,
}: {
  side: VersusSide
  which: 'player' | 'opponent'
  scoreLabel?: string
  formatScore?: (value: number) => string
}) {
  const name =
    side.label ??
    side.player?.displayName ??
    (which === 'player' ? DEFAULT_LABEL.player : DEFAULT_LABEL.opponent)

  // What it is, then its number, then how it finished. The stat inside carries
  // its own name and is hidden here, so the number is announced once.
  const words = [name, formatScore ? formatScore(side.score) : String(side.score)]
  if (side.outcome) words.push(OUTCOME_WORD[side.outcome])

  return (
    <div
      className="gs-versus__side"
      data-gs-side={which}
      data-gs-player={side.player?.id}
      data-gs-team={side.team}
      data-gs-outcome={side.outcome}
      role="group"
      aria-label={words.join(', ')}
    >
      {side.team !== undefined && side.player === undefined ? (
        // A team is not a player with a different id: no avatar case, no
        // presence, so it is a name and not an identity.
        <span className="gs-versus__label" data-gs-scope="versus" data-gs-part="label" aria-hidden="true">
          {name}
        </span>
      ) : (
        // Specimen 3f draws each side at identity's large step: the hero-size
        // disc with the name in the title face beside it. The side's grid in
        // versus.css stands the score under the name.
        <Identity player={side.player ?? null} label={side.label} size="large" aria-hidden="true" />
      )}
      <Stat
        kind="score"
        value={side.score}
        label={scoreLabel}
        format={formatScore}
        aria-hidden="true"
      />
      {side.outcome === undefined ? null : (
        // Emphasis, not motion: the mark appears with the outcome and does not
        // move, so it survives reduced motion. It is what a player who cannot
        // tell the player colour from the opponent colour reads instead.
        <span
          className="gs-versus__glyph"
          data-gs-scope="versus"
          data-gs-part="glyph"
          data-gs-animates="emphasis"
        >
          <OutcomeGlyph outcome={side.outcome} />
        </span>
      )}
    </div>
  )
}

export function Versus({
  player,
  opponent,
  label = 'Head to head',
  divider = 'vs',
  scoreLabel,
  formatScore,
  split = true,
  className,
  style,
  ...rest
}: VersusProps) {
  const fraction = share(player.score, opponent.score)

  return (
    <div
      {...rest}
      className={['gs-versus', className].filter(Boolean).join(' ')}
      // The share is geometry rather than meaning, so it is a custom property
      // and not an attribute, the same decision `progress-bar` made about how
      // far through something is.
      style={{ ...style, '--gs-versus-share': fraction } as React.CSSProperties}
      data-gs-component="versus"
      role="group"
      aria-label={label}
    >
      <Side side={player} which="player" scoreLabel={scoreLabel} formatScore={formatScore} />
      <span className="gs-versus__divider gs-display-type" data-gs-scope="versus" data-gs-part="label" aria-hidden="true">
        {divider}
      </span>
      <Side side={opponent} which="opponent" scoreLabel={scoreLabel} formatScore={formatScore} />
      {split ? (
        // The bar is a second rendering of two numbers that are already on
        // screen and already announced, so it is hidden rather than announced
        // again. The fill travels, so it is motion and stops dead under reduced
        // motion, where the two scores still say who is ahead.
        <div className="gs-versus__track" data-gs-scope="versus" data-gs-part="track" aria-hidden="true">
          <div
            className="gs-versus__fill"
            data-gs-scope="versus"
            data-gs-part="fill"
            data-gs-animates="motion"
          />
        </div>
      ) : null}
    </div>
  )
}

/* Versus. Every value comes from a token; nothing here is a literal colour.

   The numbers are specimen 3f's, measured by design/twins/3f.json against the
   drawing with scripts/twin. Where the drawing uses a value no token carries,
   the twins file says which token stands in and why. */

.gs-versus {
  /* The fraction of the bar the player's side holds. Declared here too so the
     track has a sane geometry before React writes the real one. */
  --gs-versus-share: 0.5;

  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: var(--gs-space-4);
  container-type: inline-size;

  /* A dark slab, not a card: the drawing fills the block with the edge colour
     and gives it the large-sheet radius and no outline. 18 by 22 in the
     drawing; 16 by 24 are the nearest steps. */
  padding: var(--gs-space-4) var(--gs-space-6);
  background: var(--gs-color-edge);
  border-radius: var(--gs-radius-xl);

  font-family: var(--gs-type-body-font-family);
  color: var(--gs-color-ink);
}

/* -- a side ---------------------------------------------------------------- */
/* The disc, then a column of the name over the score, 14px apart. Identity
   renders the disc and the name as one row, so the side is a grid and identity
   dissolves into it (display: contents): its avatar spans both rows in the
   first column and its name takes the first row of the second, where the score
   joins it underneath. The outcome mark has the third column. */
.gs-versus__side {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  column-gap: var(--gs-space-inset);
  align-items: center;
  min-inline-size: 0;
}

.gs-versus__side > [data-gs-component='identity'] {
  display: contents;
}

.gs-versus__side [data-gs-component='identity'] [data-gs-part='avatar'] {
  grid-column: 1;
  grid-row: 1 / 3;
}

.gs-versus__side [data-gs-component='identity'] > .gs-identity__text,
.gs-versus__label {
  grid-column: 2;
  grid-row: 1;
  align-self: end;
  min-inline-size: 0;
}

/* A name in the title face beside a 64px disc has one line, as drawn. Identity
   wraps a long name anywhere, which in a head-to-head split "AstroFury" into
   "AstroFur" and "y" at a phone width; here it truncates instead, and the
   accessible name still carries the whole of it. */
.gs-versus__side [data-gs-component='identity'] [data-gs-part='label'],
.gs-versus__label {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.gs-versus__side > [data-gs-component='stat'] {
  grid-column: 2;
  grid-row: 2;
  align-self: start;
}

.gs-versus__glyph {
  grid-column: 3;
  grid-row: 1 / 3;
}

/* The opponent reads right to left, so the two sides mirror each other around
   the divider rather than both running from the left. */
.gs-versus__side[data-gs-side='opponent'] {
  grid-template-columns: auto minmax(0, 1fr) auto;
  text-align: end;
  justify-items: end;
}

.gs-versus__side[data-gs-side='opponent'] [data-gs-component='identity'] [data-gs-part='avatar'] {
  grid-column: 3;
}

.gs-versus__side[data-gs-side='opponent'] .gs-versus__glyph {
  grid-column: 1;
}

/* A team has no disc, so its name and score take the disc's column too. */
.gs-versus__label,
.gs-versus__label + [data-gs-component='stat'] {
  grid-column: 1 / 3;
}

.gs-versus__side[data-gs-side='opponent'] .gs-versus__label,
.gs-versus__side[data-gs-side='opponent'] .gs-versus__label + [data-gs-component='stat'] {
  grid-column: 2 / 4;
}

/* The disc wears the side's colour as its ring. The drawing draws it 4px; the
   3px ui stroke is the nearest token. */
.gs-versus__side [data-gs-component='identity'][data-gs-size] [data-gs-part='avatar'] {
  /* Border-box, as drawn: the 64px disc is 64px with its ring. */
  box-sizing: border-box;
  border-width: var(--gs-stroke-ui);
}

.gs-versus__side[data-gs-side='player'] [data-gs-component='identity'] [data-gs-part='avatar'] {
  border-color: var(--gs-color-player);
}

.gs-versus__side[data-gs-side='opponent'] [data-gs-component='identity'] [data-gs-part='avatar'] {
  border-color: var(--gs-color-opponent);
}

/* A team's name, in the same face and size identity gives a player's at the
   large step, so the two kinds of side line up. */
.gs-versus__label {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  overflow-wrap: anywhere;
}

/* The score carries the side's colour: the player's in the player colour, the
   opponent's in theirs. The number is the score token, 34px in arcade, exactly
   as drawn. The word "score" is in the side's accessible name already, so the
   stat's own label is not drawn, and the number's shadow is the display
   shadow the theme gives every hero number. */
.gs-versus__side > [data-gs-component='stat'] [data-gs-part='label'] {
  display: none;
}

.gs-versus__side[data-gs-side='player'] > [data-gs-component='stat'] .gs-stat__value {
  color: var(--gs-color-player);
}

.gs-versus__side[data-gs-side='opponent'] > [data-gs-component='stat'] .gs-stat__value {
  color: var(--gs-color-opponent);
}

/* "VS", in the title face at the drawing's weight, the warning colour, and the
   display shadow, which arrives with the gs-display-type class on the element
   and is overridden here down to the title size. The drawing sets it 22px;
   the title's 20 is the nearest. */
.gs-versus__divider {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: 1;
  color: var(--gs-color-warning);
  text-transform: uppercase;
}

/* -- the outcome ----------------------------------------------------------- */
.gs-versus__glyph {
  display: inline-flex;
  align-items: center;
  transition: color var(--gs-motion-emphasis) ease-out;
}

.gs-versus__side[data-gs-outcome='win'] .gs-versus__glyph {
  color: var(--gs-color-positive-solid);
}

.gs-versus__side[data-gs-outcome='loss'] .gs-versus__glyph {
  color: var(--gs-color-negative-solid);
}

.gs-versus__side[data-gs-outcome='draw'] .gs-versus__glyph {
  color: var(--gs-color-muted);
}

/* -- the split ------------------------------------------------------------- */
/* One track, one fill: the fill is the player's share and the track behind it
   is the opponent's, which is why there is only one element to animate. The
   drawing draws an 18px pill; 16 is the nearest step. */
.gs-versus__track {
  grid-column: 1 / -1;
  block-size: var(--gs-space-4);
  overflow: hidden;
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-opponent);
  box-shadow: var(--gs-depth-flat);
}

.gs-versus__fill {
  block-size: 100%;
  inline-size: calc(var(--gs-versus-share) * 100%);
  background: var(--gs-color-player);
  /* BDS-022: a value travelling to its target runs over motion.fill. Only the
     width is timed, so reduced motion lands it at once and the two scores,
     which never moved, still say who is ahead. */
  transition: inline-size var(--gs-motion-fill) ease-out;
}

/* -- narrow ---------------------------------------------------------------- */
/* Under 400px the two sides do not have room for a 64px disc beside a name
   and a 34px score: at a 342px gallery card the player's name came out as
   "Y…" and the opponent's ran under the VS. The drawing is 420 wide and never
   has to solve this. Below that, each side stacks: disc, name, score, centred,
   and the VS keeps the middle. */
@container (max-width: 399px) {
  .gs-versus__side,
  .gs-versus__side[data-gs-side='opponent'] {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto auto;
    justify-items: center;
    text-align: center;
  }
  .gs-versus__side [data-gs-component='identity'] [data-gs-part='avatar'],
  .gs-versus__side[data-gs-side='opponent'] [data-gs-component='identity'] [data-gs-part='avatar'] {
    grid-column: 1;
    grid-row: 1;
  }
  .gs-versus__side [data-gs-component='identity'] > .gs-identity__text,
  .gs-versus__side .gs-versus__label,
  .gs-versus__side[data-gs-side='opponent'] .gs-versus__label {
    grid-column: 1;
    grid-row: 2;
    max-inline-size: 100%;
  }
  .gs-versus__side > [data-gs-component='stat'],
  .gs-versus__side[data-gs-side='opponent'] .gs-versus__label + [data-gs-component='stat'] {
    grid-column: 1;
    grid-row: 3;
  }
  .gs-versus__side .gs-versus__glyph,
  .gs-versus__side[data-gs-side='opponent'] .gs-versus__glyph {
    grid-column: 1;
    grid-row: 1;
  }
  /* A stacked side is about 120px wide; a nine letter name in the 20px title
     face is 110 and truncated to "AstroF…". Label size holds it. */
  .gs-versus__side [data-gs-component='identity'][data-gs-size] [data-gs-part='label'],
  .gs-versus__side .gs-versus__label {
    font-size: var(--gs-type-label-font-size);
  }
}
